import { expect, test } from './browser-test.ts';
import { exportedSnapshot, loadFixedBoard } from './game-fixture.ts';

test('renaming between fractional clock readings preserves all elapsed and pending time', async ({ page }) => {
  // Drive the monotonic reading directly while browser timers retain their normal lifecycle.
  await page.addInitScript(() => {
    let now = 0;
    Object.defineProperty(performance, 'now', { configurable: true, value: () => now });
    document.addEventListener('deal-name-clock', (event) => {
      if (event instanceof CustomEvent && typeof event.detail === 'number') now = event.detail;
    });
  });
  const setNow = (now: number) => page.evaluate((value) => {
    document.dispatchEvent(new CustomEvent('deal-name-clock', { detail: value }));
  }, now);
  await loadFixedBoard(page);
  await setNow(1.25);
  await page.locator('.card').nth(0).click();
  await setNow(2.25);
  await page.locator('.card').nth(1).click();
  await page.locator('summary').click();
  await setNow(3.5);
  await page.getByLabel('Deal name', { exact: true }).fill('Café');
  await setNow(4.25);
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({
    version: 2, name: 'Café', elapsedMs: 3,
    selection: { kind: 'mismatch', first: 0, second: 1, remainingMs: 798 },
  });
  await setNow(802);
  expect(await exportedSnapshot(page)).toMatchObject({
    elapsedMs: 800, selection: { kind: 'mismatch', remainingMs: 1 },
  });
  await setNow(802.25);
  expect(await exportedSnapshot(page)).toMatchObject({
    elapsedMs: 801, selection: { kind: 'closed' },
  });
});

