import { decodeSnapshot, encodeSnapshot, NAMED_SNAPSHOT_VERSION, SNAPSHOT_MAX_BYTES } from './snapshot.ts';
import { isJsonObject } from './saved-format.ts';
import { EXAMPLE_CODE, EXAMPLE_PAIRS } from './game.fixture.ts';

function namedSnapshot(overrides: Record<string, unknown> = {}): string {
  return JSON.stringify({
    version: 2,
    name: 'Café',
    boardCode: 'np1-4-1',
    matched: [],
    selection: { kind: 'closed' },
    moves: 0,
    elapsedMs: 0,
    started: false,
    ...overrides,
  });
