  assert.deepEqual(value, {
    version: 1,
    boardCode: 'np1-4-1',
    matched: [],
    selection: { kind: 'closed' },
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
  assert.deepEqual(decodeSnapshot(text), state);
  assert.equal(decodeSnapshot(text)?.name, '');
});

