test('export reads the active clock between render ticks', async ({ page }) => {
  expect(ACTIVE_MS % CLOCK_INTERVAL_MS).not.toBe(0);
  expect(PENDING_MS % CLOCK_INTERVAL_MS).not.toBe(0);
